import{_ as e,o as r,c as o,a0 as d}from"./chunks/framework.jwovEGr5.js";const m=JSON.parse('{"title":"System status visibility & error recovery","description":"","frontmatter":{},"headers":[],"relativePath":"a11y/status-and-recovery.md","filePath":"a11y/status-and-recovery.md"}'),a={name:"a11y/status-and-recovery.md"};function s(c,t,i,n,l,h){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="system-status-visibility-error-recovery" tabindex="-1">System status visibility &amp; error recovery <a class="header-anchor" href="#system-status-visibility-error-recovery" aria-label="Permalink to &quot;System status visibility &amp; error recovery&quot;">​</a></h1><p>Maps to Nielsen H1 (status visibility) and H5/H9 (error prevention &amp; recovery). Ties to <strong>FR-004</strong> health/status acceptance (<code>tests/fr004_*.rs</code>).</p><h2 id="status-surfaces-fr-004" tabindex="-1">Status surfaces (FR-004) <a class="header-anchor" href="#status-surfaces-fr-004" aria-label="Permalink to &quot;Status surfaces (FR-004)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Command / URL</th><th>What it shows</th></tr></thead><tbody><tr><td>CLI</td><td><code>sharecli status</code></td><td>Pool / process summary</td></tr><tr><td>HTTP</td><td><code>GET /health</code></td><td>Liveness JSON</td></tr><tr><td>HTTP</td><td><code>GET /health/processes</code></td><td>Process list for probes</td></tr><tr><td>HTTP</td><td><code>GET /metrics/prometheus</code></td><td>RED metrics</td></tr><tr><td>Dashboard</td><td><code>GET /</code> (WebSocket <code>/ws</code>)</td><td>Live process table + connection/thermal state</td></tr><tr><td>TUI</td><td>Thermal gauge + build-slot bar</td><td>Poll count, last poll age, thermal level</td></tr></tbody></table><p>Use <code>--verbose</code> on CLI commands for additional stderr detail during troubleshooting.</p><h2 id="degraded-mode" tabindex="-1">Degraded mode <a class="header-anchor" href="#degraded-mode" aria-label="Permalink to &quot;Degraded mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>User-visible behavior</th><th>Recovery hint</th></tr></thead><tbody><tr><td>Invalid config</td><td>Field-path error on stderr, non-zero exit</td><td>Fix path noted in message; run <code>sharecli config validate</code></td></tr><tr><td>Unknown subcommand</td><td><code>error: unrecognized subcommand</code> + suggestion</td><td>Run <code>sharecli --help</code> or <code>sharecli &lt;cmd&gt; --help</code></td></tr><tr><td>WebSocket down</td><td>Dashboard: <code>disconnected — reconnecting in 3s</code></td><td>Ensure <code>sharecli serve</code> is running on port 9000</td></tr><tr><td>Thermal poll failure</td><td>TUI assumes GREEN, continues</td><td>Check platform thermal APIs; see README thermal section</td></tr><tr><td>Auth failure on <code>serve</code></td><td>HTTP 401 + metric <code>sharecli_http_unauthorized_total</code></td><td>See <code>docs/ops/AUTH.md</code></td></tr></tbody></table><p>Config validation prints field paths before exit (<code>src/config_validator.rs</code>). Integration tests cover unknown-subcommand recovery (<code>tests/integration_cli.rs</code>).</p><h2 id="long-running-operations" tabindex="-1">Long-running operations <a class="header-anchor" href="#long-running-operations" aria-label="Permalink to &quot;Long-running operations&quot;">​</a></h2><ul><li><code>sharecli serve</code>: Ctrl-C triggers clean shutdown (<code>src/commands/serve.rs</code>).</li><li><code>sharecli report --watch</code>: Ctrl-C cancels watch mode.</li><li>TUI: progress via gauge + footer poll counter (no silent blocking).</li></ul><p>Future: <code>indicatif</code> ETA bars for multi-minute CLI ops (tracked in C09 backlog).</p>',11)])])}const p=e(a,[["render",s]]);export{m as __pageData,p as default};
